materials.vertex:
varying float vUp; varying float vWy;
void main() {
  vec4 w = modelMatrix * vec4(position, 1.0);
  vWy = w.y;
  vUp = normalize(mat3(modelMatrix) * normal).y;
  gl_Position = projectionMatrix * viewMatrix * w;
}

materials.fragment:
uniform vec3 uCol; uniform float uLift; uniform float uClipY; uniform float uOpacity; uniform float uPropA;
uniform float uBodyL; uniform float uPropTop; uniform float uPropSide; uniform float uPropC; uniform float uPropH;
varying float vUp; varying float vWy;
vec3 oklch(float L, float C, float h) {
  float a = C * cos(h), b = C * sin(h);
  float l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  float m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  float s_ = L - 0.0894841775 * a - 1.2914855480 * b;
  l_ = l_ * l_ * l_; m_ = m_ * m_ * m_; s_ = s_ * s_ * s_;
  return max(vec3(4.0767416621 * l_ - 3.3077115913 * m_ + 0.2309699292 * s_,
                 -1.2684380046 * l_ + 2.6097574011 * m_ - 0.3413193965 * s_,
                 -0.0041960863 * l_ - 0.7034186147 * m_ + 1.7076147010 * s_), 0.0);
}
void main() {
  if (vWy < uClipY) discard;
  float up = step(0.25, vUp);

  vec3 c = uBodyL < 0.0 ? uCol * mix(0.68, 1.0, up) * uLift : oklch(uBodyL + mix(uPropSide, uPropTop, up), uPropC, uPropH);
  gl_FragColor = vec4(c, uOpacity * uPropA);
}

